"use client";

/**
 * Almanac — dedicated full-reference page for the lunar almanac.
 *
 * Shows all 8 moon phases with complete gardening, lifestyle, weather,
 * and folk wisdom guidance. The current phase is highlighted.
 *
 * Accessible from the Ritual tab via "View full almanac" link.
 */

import { useState, useMemo } from "react";
import { useRouter } from "next/navigation";
import {
  FULL_ALMANAC,
  getMoonPhase,
  type AlmanacPhaseEntry,
  type AlmanacLifeTip,
} from "@/lib/celestialCalendar";

// ─── CATEGORY FILTER ─────────────────────────────────────────────────────────

const LIFE_CATEGORIES = [
  { key: "all", label: "All Tips", icon: "✦" },
  { key: "Baby & Kids", label: "Baby & Kids", icon: "👶" },
  { key: "Hair & Beauty", label: "Hair & Beauty", icon: "💇" },
  { key: "Health", label: "Health", icon: "🩺" },
  { key: "Home", label: "Home", icon: "🏠" },
  { key: "Money", label: "Money", icon: "💰" },
  { key: "Relationships", label: "Relationships", icon: "💕" },
  { key: "Cooking & Preserving", label: "Cooking", icon: "🫙" },
  { key: "Fishing & Outdoors", label: "Outdoors", icon: "🎣" },
];

// ─── COMPONENT ───────────────────────────────────────────────────────────────

export default function AlmanacPage() {
  const router = useRouter();
  const today = useMemo(() => new Date(), []);
  const currentMoon = useMemo(() => getMoonPhase(today), [today]);

  const [expandedPhase, setExpandedPhase] = useState<string | null>(currentMoon.phase);
  const [categoryFilter, setCategoryFilter] = useState("all");
  const [viewMode, setViewMode] = useState<"phases" | "category">("phases");

  // When in category view, gather tips across all phases for that category
  const categoryTips = useMemo(() => {
    if (categoryFilter === "all") return null;
    return FULL_ALMANAC.map(entry => ({
      phase: entry,
      tip: entry.almanac.lifeTips.find(t => t.category === categoryFilter),
    })).filter(t => t.tip) as { phase: AlmanacPhaseEntry; tip: AlmanacLifeTip }[];
  }, [categoryFilter]);

  return (
    <main className="flex-1 flex flex-col min-h-screen bg-background">
      {/* Header */}
      <div className="sticky top-0 z-40 bg-background/95 backdrop-blur-sm border-b border-foreground/15">
        <div className="max-w-lg mx-auto px-5 py-4 flex items-center gap-3">
          <button
            onClick={() => router.back()}
            className="w-8 h-8 flex items-center justify-center rounded-full bg-foreground/5 hover:bg-foreground/10 transition-colors"
          >
            <svg className="w-4 h-4 text-foreground/50" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7" />
            </svg>
          </button>
          <div>
            <h1 className="text-xl text-foreground" style={{ fontFamily: "'Ahsing', 'Playfair Display', serif" }}>
              Almanac
            </h1>
            <p className="text-foreground/35 text-[11px]">
              Lunar wisdom for daily life
            </p>
          </div>
        </div>
      </div>

      <div className="max-w-lg mx-auto w-full px-5 py-5 pb-12">
        {/* Current phase banner */}
        <div className="rounded-2xl bg-[#7a8c6e]/8 border border-[#7a8c6e]/15 p-4 mb-5">
          <div className="flex items-center gap-3 mb-2">
            <span className="text-3xl">{currentMoon.emoji}</span>
            <div>
              <p className="text-foreground text-base font-medium" style={{ fontFamily: "'Ahsing', 'Playfair Display', serif" }}>
                Currently: {currentMoon.label}
              </p>
              <p className="text-foreground/35 text-[11px]">
                {currentMoon.illumination}% illumination
              </p>
            </div>
          </div>
          <p className="text-foreground/50 text-[12px] leading-relaxed">
            {currentMoon.energy}
          </p>
        </div>

        {/* View mode toggle */}
        <div className="flex gap-2 mb-4">
          <button
            onClick={() => { setViewMode("phases"); setCategoryFilter("all"); }}
            className={`flex-1 py-2 rounded-lg text-xs font-medium tracking-wide transition-all ${
              viewMode === "phases"
                ? "bg-terracotta text-cream"
                : "bg-foreground/5 text-foreground/40"
            }`}
          >
            By Moon Phase
          </button>
          <button
            onClick={() => setViewMode("category")}
            className={`flex-1 py-2 rounded-lg text-xs font-medium tracking-wide transition-all ${
              viewMode === "category"
                ? "bg-terracotta text-cream"
                : "bg-foreground/5 text-foreground/40"
            }`}
          >
            By Life Area
          </button>
        </div>

        {/* ── BY LIFE AREA VIEW ── */}
        {viewMode === "category" && (
          <>
            {/* Category pills */}
            <div className="flex gap-2 overflow-x-auto pb-3 -mx-1 px-1 scrollbar-none mb-3">
              {LIFE_CATEGORIES.filter(c => c.key !== "all").map((cat) => (
                <button
                  key={cat.key}
                  onClick={() => setCategoryFilter(cat.key)}
                  className={`flex-shrink-0 px-3 py-1.5 rounded-full text-[11px] font-medium tracking-wide transition-all flex items-center gap-1.5 ${
                    categoryFilter === cat.key
                      ? "bg-terracotta text-cream"
                      : "bg-foreground/5 text-foreground/40"
                  }`}
                >
                  <span className="text-xs">{cat.icon}</span>
                  {cat.label}
                </button>
              ))}
            </div>

            {/* Tips for selected category across all phases */}
            {categoryFilter !== "all" && categoryTips && (
              <div className="flex flex-col gap-2">
                {categoryTips.map(({ phase, tip }) => {
                  const isCurrent = phase.phase === currentMoon.phase;
                  return (
                    <div
                      key={phase.phase}
                      className={`rounded-xl border p-4 transition-all ${
                        isCurrent
                          ? "bg-sage/8 border-sage/20"
                          : "bg-white/50 border-foreground/15"
                      }`}
                    >
                      <div className="flex items-center gap-2.5 mb-2">
                        <span className="text-lg">{phase.emoji}</span>
                        <span className={`text-sm font-medium ${isCurrent ? "text-sage" : "text-foreground/70"}`}>
                          {phase.label}
                        </span>
                        <span className="text-foreground/25 text-[10px]">{phase.daysInCycle}</span>
                        {isCurrent && (
                          <span className="text-[9px] px-1.5 py-0.5 rounded-full bg-sage/15 text-sage font-semibold tracking-wider uppercase">Now</span>
                        )}
                      </div>
                      <p className="text-foreground/55 text-[13px] leading-relaxed">{tip.tip}</p>
                    </div>
                  );
                })}
              </div>
            )}

            {categoryFilter === "all" && (
              <p className="text-foreground/30 text-sm text-center py-8">
                Pick a life area above to see tips across all moon phases.
              </p>
            )}
          </>
        )}

        {/* ── BY MOON PHASE VIEW ── */}
        {viewMode === "phases" && (
          <div className="flex flex-col gap-2">
            {FULL_ALMANAC.map((entry) => {
              const isCurrent = entry.phase === currentMoon.phase;
              const isOpen = expandedPhase === entry.phase;

              return (
                <div
                  key={entry.phase}
                  className={`rounded-xl border transition-all duration-200 ${
                    isCurrent
                      ? "bg-sage/8 border-sage/20"
                      : isOpen
                      ? "bg-surface/80 border-foreground/18"
                      : "bg-white/45 border-foreground/15"
                  }`}
                >
                  <button
                    onClick={() => setExpandedPhase(isOpen ? null : entry.phase)}
                    className="w-full text-left px-4 py-3.5 flex items-center gap-3"
                  >
                    <span className="text-xl w-7 text-center flex-shrink-0">{entry.emoji}</span>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <span className={`text-sm font-medium ${isCurrent ? "text-sage" : "text-foreground/70"}`}>
                          {entry.label}
                        </span>
                        {isCurrent && (
                          <span className="text-[9px] px-1.5 py-0.5 rounded-full bg-sage/15 text-sage font-semibold tracking-wider uppercase">Now</span>
                        )}
                      </div>
                      <span className="text-foreground/30 text-[11px]">{entry.daysInCycle}</span>
                    </div>
                    <svg
                      className={`w-4 h-4 text-foreground/20 flex-shrink-0 transition-transform duration-200 ${isOpen ? "rotate-90" : ""}`}
                      fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}
                    >
                      <path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7" />
                    </svg>
                  </button>

                  <div className={`overflow-hidden transition-all duration-300 ease-out ${isOpen ? "max-h-[3000px] opacity-100" : "max-h-0 opacity-0"}`}>
                    <div className="px-4 pb-5 pt-0">
                      <div className="h-px bg-foreground/8 mb-4" />

                      {/* Energy */}
                      <p className="text-foreground/55 text-[13px] leading-relaxed mb-4 italic">{entry.energy}</p>

                      {/* ── GARDENING ── */}
                      <div className="mb-4">
                        <div className="flex items-center gap-2 mb-2">
                          <span className="text-sm">🌱</span>
                          <p className="text-[11px] text-sage uppercase tracking-widest font-semibold">Gardening</p>
                        </div>
                        <p className="text-foreground/55 text-[12px] leading-relaxed mb-2">{entry.almanac.gardening}</p>
                        <div className="flex gap-4">
                          <div className="flex-1">
                            <p className="text-[10px] text-sage/70 uppercase tracking-wider mb-1">Best for</p>
                            <div className="flex flex-wrap gap-1">
                              {entry.almanac.bestFor.map((item, i) => (
                                <span key={i} className="text-[10px] bg-sage/10 text-sage/80 px-2 py-0.5 rounded-full">{item}</span>
                              ))}
                            </div>
                          </div>
                          <div className="flex-1">
                            <p className="text-[10px] text-[#c45d3e]/60 uppercase tracking-wider mb-1">Avoid</p>
                            <div className="flex flex-wrap gap-1">
                              {entry.almanac.avoid.map((item, i) => (
                                <span key={i} className="text-[10px] bg-[#c45d3e]/8 text-[#c45d3e]/60 px-2 py-0.5 rounded-full">{item}</span>
                              ))}
                            </div>
                          </div>
                        </div>
                      </div>

                      {/* ── LIFE TIPS ── */}
                      <div className="mb-4">
                        <div className="flex items-center gap-2 mb-2">
                          <span className="text-sm">🌾</span>
                          <p className="text-[11px] text-amber uppercase tracking-widest font-semibold">Life Almanac</p>
                        </div>
                        <div className="grid gap-2">
                          {entry.almanac.lifeTips.map((tip, i) => (
                            <div key={i} className="rounded-lg bg-foreground/[0.03] border border-foreground/15 px-3.5 py-3">
                              <div className="flex items-center gap-2 mb-1">
                                <span className="text-sm">{tip.icon}</span>
                                <span className="text-[11px] text-foreground/50 font-semibold tracking-wide">{tip.category}</span>
                              </div>
                              <p className="text-foreground/55 text-[12px] leading-relaxed">{tip.tip}</p>
                            </div>
                          ))}
                        </div>
                      </div>

                      {/* ── WEATHER LORE ── */}
                      <div className="mb-3">
                        <div className="flex items-center gap-2 mb-1.5">
                          <span className="text-sm">🌤</span>
                          <p className="text-[11px] text-foreground/40 uppercase tracking-widest font-semibold">Weather Lore</p>
                        </div>
                        <p className="text-foreground/50 text-[12px] leading-relaxed">{entry.almanac.weatherLore}</p>
                      </div>

                      {/* ── FOLK WISDOM ── */}
                      <div className="rounded-lg bg-foreground/[0.03] border border-foreground/15 px-3.5 py-3">
                        <div className="flex items-center gap-2 mb-1">
                          <span className="text-sm">📖</span>
                          <span className="text-[11px] text-foreground/40 uppercase tracking-widest font-semibold">Folk Wisdom</span>
                        </div>
                        <p className="text-foreground/40 text-[12px] leading-relaxed italic">{entry.almanac.folkWisdom}</p>
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </main>
  );
}
